/// Computes the truncated length based on the rules:
/// - If `n > m`, returns `n - m`.
/// - Otherwise, returns `1`.
fn trunc_len(n: usize, m: usize) -> usize {
    if n > m {
        n - m
    } else {
        1
    }
}

/// Truncates the input vector `c` according to the rules:
/// - If `m == 0`, returns `c` unchanged.
/// - If `0 < m < c.len()`, returns the first `c.len() - m` elements.
/// - If `m >= c.len()`, returns a vector of length 1 containing `c[0]`.
///
/// The parameter `scl` is not used in this computation.
fn legder(c: Vec<f64>, m: u8, _scl: f64) -> Vec<f64> {
    let m_usize = m as usize;
    let keep = trunc_len(c.len(), m_usize);
    c.into_iter().take(keep).collect()
}

